import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"AOT编译优化","link":"/guide/programming_guide/advanced_programming/aot_compilation_optimization"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aot_compilation_optimization.md","filePath":"guide/programming_guide/advanced_programming/aot_compilation_optimization.md","outlineHeaders":[{"level":2,"title":"概述","slug":"概述","link":"#概述"},{"level":2,"title":"核心原理","slug":"核心原理","link":"#核心原理"},{"level":2,"title":"整体流程","slug":"整体流程","link":"#整体流程"},{"level":3,"title":"核函数（Kernel）常量化预编译","slug":"核函数（Kernel）常量化预编译","link":"#核函数（Kernel）常量化预编译"},{"level":3,"title":"Host在运行时选择特定核函数（Kernel）","slug":"Host在运行时选择特定核函数（Kernel）","link":"#Host在运行时选择特定核函数（Kernel）"},{"level":3,"title":"完整示例","slug":"完整示例","link":"#完整示例"},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项"}],"lastUpdated":1787050286000}'),c={name:"guide/programming_guide/advanced_programming/aot_compilation_optimization.md"};function t(i,s,e,o,g,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>AOT编译优化</h1><h2 id="概述">概述<a class="header-anchor" href="#概述">​</a></h2><p>AOT（Ahead-of-Time，提前编译）编译优化是一种将运行时参数提前到编译阶段常量化的性能优化技术。通过在编译阶段对核函数（Kernel）进行额外的常量化编译，在运行时根据Tiling参数自动匹配预编译的特化版本，让编译器能够进行更深度的优化（如循环展开、死代码消除、常量传播等），从而获得超越通用版本的执行性能。</p><h2 id="核心原理">核心原理<a class="header-anchor" href="#核心原理">​</a></h2><p>在Ascend C算子开发中，Tiling参数（如矩阵分块大小、操作类型等）通常在运行时由Host侧计算并传入核函数（Kernel）。通用版本核函数（Kernel）以变量形式使用这些参数，无法深度优化。</p><p>AOT的核心思想是：<strong>将特定Tiling配置以编译期常量的形式固化到模板代码中</strong>，让编译器在编译阶段就能看到这些值，进一步实现：</p><ul><li><strong>循环展开</strong>：基于常量边界完全展开内层循环，消除循环控制开销。</li><li><strong>常量传播</strong>：在编译期计算所有依赖Tiling常量的表达式，减少运行时的标量计算。</li><li><strong>死代码消除</strong>：根据常量操作类型、分块大小裁剪永远不会执行的条件分支减少执行代码量，降低ICache Miss比率。</li></ul><h2 id="整体流程">整体流程<a class="header-anchor" href="#整体流程">​</a></h2><h3 id="核函数（Kernel）常量化预编译">核函数（Kernel）常量化预编译<a class="header-anchor" href="#核函数（Kernel）常量化预编译">​</a></h3><ul><li><p>根据算子的典型Shape和输入，编写Tiling常量模板定义</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">struct</span><span class="w"> </span><span class="nc">TilingData</span><span class="p">;</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="k">struct</span><span class="w"> </span><span class="nc">ConstTilingHolder</span><span class="w"> </span><span class="p">{</span><span class="w"> </span><span class="c1">// 持有特定Tiling的常量结构体</span>
<span class="w">    </span><span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">bytes</span><span class="p">[]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">3</span><span class="p">,</span><span class="w"> </span><span class="p">...};</span><span class="w">  </span><span class="c1">// 常量特化Tiling值（数组）</span>
<span class="w">    </span><span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">T</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">convert_from_bytes</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">(</span><span class="n">bytes</span><span class="p">);</span><span class="w"> </span><span class="c1">// 编译期转为常量结构体</span>
<span class="p">};</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="k">struct</span><span class="w"> </span><span class="nc">RuntimeTilingHolder</span><span class="w"> </span><span class="p">{</span><span class="w"> </span><span class="c1">// 用于区分常量Tiling的运行时桩结构体</span>
<span class="w">    </span><span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">bytes</span><span class="p">[</span><span class="k">sizeof</span><span class="p">(</span><span class="n">T</span><span class="p">)]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{};</span><span class="w">  </span><span class="c1">// 数据桩实现，该值无意义</span>
<span class="w">    </span><span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">T</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">convert_from_bytes</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">(</span><span class="n">bytes</span><span class="p">);</span>
<span class="p">};</span>
</code></pre></div></li><li><p>核函数（Kernel）实现，常量Tiling与运行时Tiling变量合一的代码实现</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 对外提供模板类型，用于Host调用时不同场景给定常量Tiling值或者运行时桩</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">TH</span><span class="o">&gt;</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x1</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x2</span><span class="p">,</span><span class="w"> </span><span class="n">TilingData</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">TilingData</span><span class="w"> </span><span class="o">*</span><span class="n">td</span><span class="p">;</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="k">constexpr</span><span class="p">(</span><span class="o">!</span><span class="n">std</span><span class="o">::</span><span class="n">is_same_v</span><span class="o">&lt;</span><span class="n">TH</span><span class="p">,</span><span class="w"> </span><span class="n">RuntimeTilingHolder</span><span class="o">&lt;</span><span class="n">TilingData</span><span class="o">&gt;&gt;</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">td</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="o">&amp;</span><span class="n">TH</span><span class="o">::</span><span class="n">value</span><span class="p">;</span><span class="w"> </span><span class="c1">// 如果调用给定的是常量Tiling值，则直接获取常量值向下传递</span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">td</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="o">&amp;</span><span class="n">tiling</span><span class="p">;</span><span class="w">  </span><span class="c1">// 如果拿到的是运行时桩，则从参数获取</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></li></ul><h3 id="Host在运行时选择特定核函数（Kernel）">Host在运行时选择特定核函数（Kernel）<a class="header-anchor" href="#Host在运行时选择特定核函数（Kernel）">​</a></h3><p>在Host调用核函数（Kernel）的代码中加入常量化Tiling匹配和调用，编译器根据指定常量Tiling模板与核函数（Kernel）混合编译实现常量核函数（Kernel）实例化。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 根据运行时计算的Tiling结果，匹配常量Tiling</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">memcmp</span><span class="p">(</span><span class="o">&amp;</span><span class="n">tiling_data</span><span class="p">,</span><span class="w"> </span><span class="n">ConstTilingHolder</span><span class="o">&lt;</span><span class="n">TilingData</span><span class="o">&gt;::</span><span class="n">bytes</span><span class="p">,</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">tiling_data</span><span class="p">))</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="c1">// 匹配上后，调用常量Tiling的核函数（Kernel）实现</span>
<span class="w">    </span><span class="n">add</span><span class="o">&lt;</span><span class="n">ConstTilingHolder</span><span class="o">&lt;</span><span class="n">TilingData</span><span class="o">&gt;&gt;&lt;&lt;&lt;</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">x1</span><span class="p">,</span><span class="w"> </span><span class="n">x2</span><span class="p">,</span><span class="w"> </span><span class="n">tiling_data</span><span class="p">);</span>
<span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="c1">// 最终常量Tiling都无法匹配的，使用运行时Tiling结果进行兜底</span>
<span class="w">    </span><span class="n">add</span><span class="o">&lt;</span><span class="n">RuntimeTilingHolder</span><span class="o">&lt;</span><span class="n">TilingData</span><span class="o">&gt;&gt;&lt;&lt;&lt;</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">x1</span><span class="p">,</span><span class="w"> </span><span class="n">x2</span><span class="p">,</span><span class="w"> </span><span class="n">tiling_data</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><h3 id="完整示例">完整示例<a class="header-anchor" href="#完整示例">​</a></h3><p>一个完整的AOT编译优化Matmul示例可参考 <a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/06_aot_compilation/matmul_aot_compilation">matmul_aot_compilation</a>。该示例演示了纯Cube场景下实现AOT编译的完整流程，并将模板方法进行提取实现了一套简易API。</p><h2 id="注意事项">注意事项<a class="header-anchor" href="#注意事项">​</a></h2><ol><li><p><strong>Tiling字节兼容性</strong>：如果算子修改了Tiling结构体，则需要确保定义的常量与当前的Tiling结构体定义一致。</p></li><li><p><strong>编译时间与二进制体积</strong>：每个AOT特化版本都会增加编译时间和二进制体积。建议只针对高频使用的配置预编译AOT版本，避免过度特化。</p></li><li><p><strong>运行时开销</strong>：常量Tiling的匹配过程增加额外Host开销，开发者需结合算子使用场景进行相应调整。</p></li></ol></article></div>`,1)])])}const h=a(c,[["render",t]]);export{w as __pageData,h as default};
